RECORDS = [('内环境、稳态与负反馈', '调节基础', '绪论与机体调节主题', '稳态指内环境变量在调节下维持相对稳定，而非恒定不变。负反馈中，调节结果减弱最初的偏离；正反馈则在特定条件下放大变化。', ['能区分稳态与绝对恒定。', '能据作用方向辨认负反馈。'], Q('调节结果使最初偏离减小，属于哪一种调节形式？', '负反馈', ['正反馈', '没有反馈的信息流', '完全无调节的随机变化'], '负反馈的定义依据调节结果对原始偏离的作用方向，而不是作用的好坏。'), Q('教学模型中，某变量升高后引起效应器作用，使该变量下降接近原水平，说明什么？', '存在抵消偏离的负反馈', ['正反馈，因为初始变化触发了后续反应', '前馈调节，因为效应器已经开始作用', '无反馈调节，因为变量最后接近原水平'], '升高触发降低方向的作用，符合负反馈；稳态仍允许一定范围内波动。')), ('跨膜转运与电化学梯度', '细胞生理', '细胞的基本功能主题', '简单扩散和易化扩散沿相应梯度进行；原发性主动转运直接耦联能量利用，继发性主动转运利用其他离子梯度。离子跨膜方向由电势和浓度共同决定。', ['能区分被动与主动转运。', '能说明继发性主动转运的能量来源。'], Q('钠钾泵直接利用哪种能量来源维持离子梯度？', 'ATP水解释放的能量', ['钠离子顺电化学梯度流动提供的能量', '细胞外钾离子被动扩散的能量', '仅靠膜两侧的渗透压差'], '钠钾泵是原发性主动转运体，直接耦联ATP水解与离子转运。'), Q('某转运体利用钠离子顺电化学梯度流入，带动葡萄糖逆浓度梯度进入细胞，这属于什么？', '继发性主动转运', ['葡萄糖的简单扩散', '由葡萄糖载体直接水解ATP驱动的原发性主动转运', '葡萄糖顺浓度梯度的易化扩散'], '葡萄糖转运间接利用钠梯度所含能量，钠梯度通常由原发性主动转运维持。')), ('静息电位、动作电位与不应期', '细胞生理', '细胞的基本功能主题', '膜电位来自离子梯度和膜对离子的选择性通透性。动作电位是一种再生性电变化；在典型神经轴突中，达到阈值后触发全或无的动作电位，并伴随不应期。', ['能区分静息电位与动作电位。', '能说明全或无特性与不应期。'], Q('在典型神经轴突中，单个动作电位的全或无特性意味着什么？', '达到触发条件后产生完整动作电位，未达到则不触发', ['任何刺激均产生任意幅度的动作电位', '动作电位幅度与刺激强度无限成正比', '所有膜电位变化都没有阈值'], '全或无描述单个动作电位；刺激强度仍可通过频率或募集等方式编码。'), Q('教学记录中，在第一个动作电位后的一小段时间内，无论第二个刺激多强都不能触发新的动作电位，符合哪一概念？', '绝对不应期', ['相对不应期', '超常期', '低常期'], '绝对不应期内主要电压门控通道尚未充分恢复，不能再产生正常的新动作电位。'), [(2, '膜电位依赖跨膜离子梯度和通透性')]), ('神经肌肉接头与兴奋收缩耦联', '细胞生理', '骨骼肌收缩主题', '神经肌肉接头把运动神经活动转为肌纤维兴奋。骨骼肌兴奋引发胞质钙升高，钙与肌钙蛋白作用改变肌丝相互作用条件，ATP参与横桥循环与钙回收。', ['能区分接头传递与肌丝收缩。', '能解释钙和ATP在收缩中的不同作用。'], Q('骨骼肌兴奋收缩耦联中，直接改变肌丝调节状态的重要细胞内信号是什么？', '胞质钙离子浓度升高', ['胞质钙离子浓度下降', '钙直接与肌动蛋白结合而无需调节蛋白', '乙酰胆碱直接进入肌节并与肌钙蛋白结合'], '胞质钙升高并与肌钙蛋白结合，使肌动蛋白上的相应结合条件改变。'), Q('关于ATP在骨骼肌活动中的作用，哪项正确？', '既参与横桥循环，也支持钙的主动回收', ['ATP只驱动钙回收而不参与横桥循环', 'ATP只用于横桥运动，钙回收完全被动', 'ATP只能使横桥结合，不能帮助横桥与肌动蛋白解离'], 'ATP为机械循环及离子泵等过程供能；结合、解离、复位分别涉及不同步骤。'), [(3, '肌纤维兴奋是兴奋收缩耦联的起点')]), ('血液成分与生理性止血', '血液与循环', '血液主题', '血液运输物质并参与防御和稳态。生理性止血包含血管反应、血小板参与和凝血等相互联系的过程；纤维蛋白有助于稳定血凝块，纤溶参与后续调控。', ['能区分血小板功能与凝血过程。', '能说明止血与纤溶的相互平衡。'], Q('凝血过程中，形成稳定网架的重要蛋白是什么？', '纤维蛋白', ['纤维蛋白原的未活化可溶形式', '白蛋白', '血红蛋白'], '纤维蛋白由纤维蛋白原转化形成，帮助稳定血凝块。'), Q('为何不能把血小板聚集与凝血完全当作同一个过程？', '两者机制不同但相互促进，共同参与止血', ['血小板聚集就是纤维蛋白原转变为纤维蛋白', '凝血只由血小板彼此黏连组成，不涉及酶促反应', '血小板与凝血在止血中彼此独立而无相互作用'], '血小板形成初步止血结构并提供反应条件；凝血涉及酶促级联和纤维蛋白生成。'), [('med_histology_004', '血细胞组成有助于理解止血过程', 'soft')]), ('心动周期、每搏量与心输出量', '血液与循环', '血液循环主题', '心脏泵血依赖心腔压力变化和瓣膜启闭。心输出量等于每搏量乘心率；舒张末期与收缩末期容积之差为每搏量，射血分数反映每搏量相对于舒张末期容积的比例。', ['能计算心输出量与射血分数。', '能用压差解释瓣膜启闭。'], Q('在教学模型中，每搏量70 mL、心率60次/分，心输出量是多少？', '4.2 L/分', ['0.42 L/分', '42 L/分', '0.13 L/分'], '70×60=4200 mL/分，即4.2 L/分。这是给定数据的演算，不是个体评估。'), Q('某心室舒张末期容积120 mL、收缩末期容积50 mL，计算所得射血分数最接近多少？', '58%', ['42%', '70%', '170%'], '每搏量=120−50=70 mL；射血分数=70/120≈58.3%。'), [('med_anatomy_008', '心腔和瓣膜结构是心动周期的基础')]), ('血流、压力差与阻力', '血液与循环', '血液循环主题', '在简化稳态模型中，血流量等于压力差除以阻力。小动脉口径影响外周阻力；实际循环还受顺应性、搏动及血液性质影响，不能无条件套用刚性管模型。', ['能在限定条件下使用流量关系。', '能解释血管半径改变对阻力的方向影响。'], Q('简化关系Q=ΔP/R中，在压差不变时阻力加倍，流量怎样变化？', '变为原来的一半', ['变为原来的两倍', '保持原值', '必然变为零'], '在压差固定且模型适用时，流量与阻力成反比。'), Q('在同长、同黏度的理想刚性圆管层流模型中，半径减为原来一半，阻力变为多少？', '原来的16倍', ['原来的2倍', '原来的4倍', '原来的1/16'], '泊肃叶关系中R与1/r⁴成正比；半径减半时阻力乘以2⁴=16。该结论仅用于题设理想模型。'), [(6, '心泵与循环相连，便于理解流量形成', 'soft')]), ('肺通气、肺泡通气与气体交换', '呼吸与消化', '呼吸主题', '肺通气由呼吸肌和胸肺力学产生，气体交换由分压差驱动。分钟通气量与肺泡通气量不同：无效腔使部分吸入气体不参与有效的肺泡换气。', ['能区分分钟通气量和肺泡通气量。', '能计算给定条件下的肺泡通气量。'], Q('气体跨肺泡气血屏障扩散的直接驱动力是什么？', '气体分压差', ['血液与组织液之间的胶体渗透压差', '毛细血管内外的静水压差', '肺泡上皮两侧的电位差'], '各气体按其分压差扩散；厚度、面积和扩散性质也影响交换速率。'), Q('教学模型中潮气量500 mL、无效腔150 mL、呼吸频率12次/分，肺泡通气量是多少？', '4.2 L/分', ['6.0 L/分', '1.8 L/分', '7.8 L/分'], '肺泡通气量=(500−150)×12=4200 mL/分；6.0 L/分是分钟通气量。'), [('med_histology_008', '肺泡结构有助于理解扩散距离与交换', 'soft')]), ('消化、吸收与胃肠调节', '呼吸与消化', '消化和吸收主题', '消化将食物大分子加工为适合吸收的形式，吸收使物质跨消化道上皮进入机体。酶、胆汁、运动和神经体液调节相互配合；胆汁盐参与脂质消化吸收，但并非消化酶。', ['能区分消化与吸收。', '能解释胆汁盐与消化酶的不同作用。'], Q('食物分解产物跨小肠上皮进入血液或淋巴的过程叫什么？', '吸收', ['消化', '胃排空', '肠道推进运动'], '吸收强调跨消化道上皮进入机体，和腔内消化分解不同。'), Q('关于胆汁盐在脂质处理中作用的说法，哪项正确？', '帮助乳化和形成混合微胶粒，促进脂质消化吸收', ['直接以脂肪酶方式水解甘油三酯酯键', '在肠腔内把脂肪酸重新合成为甘油三酯', '通过阻止混合微胶粒形成来增强脂质吸收'], '胆汁盐的物理化学作用有助于脂质处理；它不同于催化水解的脂肪酶。'), [('med_anatomy_003', '消化管与腺体连接有助于理解消化液作用', 'soft')]), ('肾滤过、重吸收、分泌与清除率', '排泄与调节', '尿的生成和排出；肾功能的评定主题', '尿中物质的排出由滤过、重吸收和分泌共同决定。清除率用排泄速率除以血浆浓度表达；某标志物须满足特定条件，其清除率才能近似代表肾小球滤过率。', ['能区分三种肾脏转运过程。', '能按单位计算清除率并说明假设。'], Q('物质由肾小管腔回到血液的过程叫什么？', '重吸收', ['肾小球滤过', '肾小管分泌', '最终尿液向体外排泄'], '重吸收是管腔至机体的回收；分泌方向相反，滤过发生在肾小体。'), Q('某教学标志物尿浓度100 mg/L、尿流量1 mL/分、血浆浓度2 mg/L，其清除率是多少？', '50 mL/分', ['2 mL/分', '100 mL/分', '200 mL/分'], 'C=U×V/P=100×1/2=50 mL/分。该计算本身不证明此物质满足估计滤过率的所有条件。'), [('med_histology_009', '肾单位和屏障结构是三种转运过程的解剖基础')]), ('激素受体、反馈与血糖调节', '排泄与调节', '内分泌主题', '激素经相应受体产生作用，靶细胞特性决定反应。胰岛素和胰高血糖素在营养代谢中分工不同；下丘脑、垂体与外周腺体之间常存在多层反馈。', ['能说明激素与靶受体的关系。', '能比较胰岛素和胰高血糖素的基本方向。'], Q('一般情况下，决定某细胞能否对一种激素产生特异反应的重要条件是什么？', '具有相应功能性受体和信号通路', ['只要激素进入血液就会让所有细胞作相同反应', '只要细胞位于激素分泌腺附近即可，不需要受体', '仅由血中激素浓度决定，与细胞信号系统无关'], '激素作用依赖受体与下游信号系统，仅血液中出现某激素并不足以保证所有细胞同样反应。'), Q('在基础生理模型中，进食后胰岛素增多，哪项代谢方向与其作用相符？', '促进相关组织摄取和储存营养物质', ['促进肝糖输出并抑制糖原合成', '促进脂肪分解并抑制营养物质储存', '主要通过抑制相关组织对葡萄糖的利用发挥作用'], '胰岛素总体促进营养摄取、利用和储存；不同组织的转运机制与反应并不完全相同。'), [(1, '内分泌反馈是稳态调节的具体形式')]), ('突触传递、整合与反射调节', '神经调节', '神经系统的功能主题', '化学突触通过递质与受体实现信息传递，突触后反应可兴奋也可抑制。多个输入在时间和空间上整合；反射由完整通路及中枢状态共同决定。', ['能区分兴奋性与抑制性突触后作用。', '能说明输入整合不同于单个动作电位。'], Q('在化学突触中，突触前信息通常通过什么到达突触后膜？', '释放的神经递质与相应受体结合', ['电流直接经缝隙连接进入突触后细胞', '突触前胞体合成的受体直接取代突触后膜', '动作电位本身经轴突内运输颗粒穿过突触间隙'], '递质释放并作用于突触后受体，是化学突触传递的核心环节。'), Q('多个较弱兴奋性输入在接近时间内共同使神经元达到阈值，说明了什么？', '突触后电位可以发生时间或空间总和', ['多个完整动作电位的幅度在线性叠加后形成更大动作电位', '阈下输入均不可对突触后细胞产生任何影响', '只要存在任何抑制性输入，所有兴奋性输入都完全失效'], '局部突触后电位可整合；单个动作电位仍有自身的全或无特性。'), [(3, '理解动作电位阈值有助于区分局部电位的整合'), ('med_anatomy_012', '反射弧结构有助于定位传入、中枢和传出环节', 'soft')]), ('能量代谢与体温调节', '整合生理', '能量代谢与体温主题', '机体从营养物质获取能量，并持续产热和散热。体温调节涉及中枢整合及效应器反应；环境温度、运动和蒸发条件影响热量交换，体温不是全身处处相同。', ['能区分产热与散热环节。', '能解释汗液蒸发的散热条件。'], Q('汗液发挥散热作用时，关键的物理过程是什么？', '蒸发吸热', ['皮肤与接触物之间的热传导', '以红外线形式进行的热辐射', '空气流动导致的对流'], '汗液蒸发需吸收热量；汗滴直接滴落而未蒸发时，不能提供相同的蒸发散热效果。'), Q('在相同产热和其他条件下，空气湿度明显升高常使哪种散热方式受限？', '汗液蒸发散热', ['辐射散热', '传导散热', '对流散热'], '较高环境湿度降低水分蒸发的驱动力；其他热交换方式还取决于温度及接触条件。'), [(1, '体温调节可用于理解反馈维持稳态')]), ('生长发育、生殖与衰老的生理变化', '整合生理', '生长发育和衰老主题', '生长涉及体量变化，发育涉及结构和功能成熟；生殖受到神经内分泌等调节。衰老是多层次、存在个体差异的过程，不能把每项功能随年龄变化都等同于疾病。', ['能区分生长与发育。', '能区分年龄相关变化与疾病结论。'], Q('描述器官结构与功能逐渐成熟时，更贴近哪个概念？', '发育', ['仅体量增加意义的生长', '损伤后的瘢痕修复', '成熟后随年龄发生的衰老'], '发育强调结构、功能的成熟和变化；生长侧重体量等数量增加。'), Q('看到某功能的群体平均值随年龄变化，最合理的推论是什么？', '需结合个体差异和其他证据，不能仅凭年龄判定疾病', ['同年龄每个人的功能必然完全相同', '年龄越大必然具有同一种疾病', '群体均值可以直接给每个人作临床结论'], '群体年龄趋势并不能消除个体差异；生理衰老与具体疾病需要区分。'), [(11, '激素调节帮助理解生长发育及生殖的整合控制', 'soft')])]
